impl<S> Router<S>
where
    S: Clone + Send + Sync + 'static,
{
    /// Create a new `Router`.
    ///
    /// Unless you add additional routes this will respond with `404 Not Found` to
    /// all requests.
    pub fn new() -> Self {
        Self {
            path_router: Default::default(),
            fallback_router: PathRouter::new_fallback(),
            default_fallback: true,
            catch_all_fallback: Fallback::Default(Route::new(NotFound)),
        }
    }

    #[doc = include_str!("../docs/routing/route.md")]
    #[track_caller]
    pub fn route(mut self, path: &str, method_router: MethodRouter<S>) -> Self {
        panic_on_err!(self.path_router.route(path, method_router));
        self
    }

    #[doc = include_str!("../docs/routing/route_service.md")]
    pub fn route_service<T>(mut self, path: &str, service: T) -> Self
    where
        T: Service<Request, Error = Infallible> + Clone + Send + 'static,
        T::Response: IntoResponse,
        T::Future: Send + 'static,
    {
        let service = match try_downcast::<Router<S>, _>(service) {
            Ok(_) => {
                panic!(
                    "Invalid route: `Router::route_service` cannot be used with `Router`s. \
                     Use `Router::nest` instead"
                );
            }
            Err(service) => service,
        };

        panic_on_err!(self.path_router.route_service(path, service));
        self
    }

    #[doc = include_str!("../docs/routing/nest.md")]
    #[track_caller]
    pub fn nest(mut self, path: &str, router: Router<S>) -> Self {
        let Router {
            path_router,
            fallback_router,
            default_fallback,
            // we don't need to inherit the catch-all fallback. It is only used for CONNECT
            // requests with an empty path. If we were to inherit the catch-all fallback
            // it would end up matching `/{path}/*` which doesn't match empty paths.
            catch_all_fallback: _,
        } = router;

        panic_on_err!(self.path_router.nest(path, path_router));

        if !default_fallback {
            panic_on_err!(self.fallback_router.nest(path, fallback_router));
        }

        self
    }

    /// Like [`nest`](Self::nest), but accepts an arbitrary `Service`.
    #[track_caller]
    pub fn nest_service<T>(mut self, path: &str, service: T) -> Self
    where
        T: Service<Request, Error = Infallible> + Clone + Send + 'static,
        T::Response: IntoResponse,
        T::Future: Send + 'static,
    {
        panic_on_err!(self.path_router.nest_service(path, service));
        self
    }

    #[doc = include_str!("../docs/routing/merge.md")]
    #[track_caller]
    pub fn merge<R>(mut self, other: R) -> Self
    where
        R: Into<Router<S>>,
    {
        let Router {
            path_router,
            fallback_router: other_fallback,
            default_fallback,
            catch_all_fallback,
        } = other.into();

        let self_default_fallback = self.default_fallback;
        self.default_fallback = panic_on_err!(self.merge_routers(
            path_router,
            other_fallback,
            self_default_fallback,
            default_fallback,
        ));

        self.catch_all_fallback = self
            .catch_all_fallback
            .merge(catch_all_fallback)
            .unwrap_or_else(|| panic!("Cannot merge two `Router`s that both have a fallback"));

        self
    }

    #[track_caller]
    fn merge_routers(
        &mut self,
        other_path_router: PathRouter<S, false>,
        other_fallback_router: PathRouter<S, true>,
        self_default_fallback: bool,
        other_default_fallback: bool,
    ) -> Result<bool, Cow<'static, str>> {
        let other_routes = other_path_router.routes;
        let other_node = other_path_router.node;

        for (id, endpoint) in other_routes {
            let path = other_node
                .route_id_to_path
                .get(&id)
                .expect("no path for route id. This is a bug in axum. Please file an issue");

            match endpoint {
                Endpoint::MethodRouter(mut method_router) => {
                    if let MethodEndpoint::BoxedHandler(handler) = method_router.get {
                        method_router.get = MethodEndpoint::BoxedHandler(BoxedIntoRoute(
                            handler.0.clone_box(),
                        ));
                    }
                    if let MethodEndpoint::BoxedHandler(handler) = method_router.head {
                        method_router.head = MethodEndpoint::BoxedHandler(BoxedIntoRoute(
                            handler.0.clone_box(),
                        ));
                    }
                    if let Fallback::BoxedHandler(handler) = method_router.fallback {
                        method_router.fallback = Fallback::BoxedHandler(BoxedIntoRoute(
                            handler.0.clone_box(),
                        ));
                    }

                    if let Some((route_id, Endpoint::MethodRouter(prev_method_router))) = self
                        .path_router
                        .node
                        .path_to_route_id
                        .get(&**path)
                        .and_then(|route_id| {
                            self.path_router
                                .routes
                                .get(route_id)
                                .map(|svc| (*route_id, svc))
                        })
                    {
                        let service = Endpoint::MethodRouter(
                            prev_method_router
                                .clone()
                                .merge_for_path(Some(path.as_ref()), method_router),
                        );
                        self.path_router.routes.insert(route_id, service);
                    } else {
                        let id = self.path_router.next_route_id();
                        let mut node = Arc::try_unwrap(Arc::clone(&self.path_router.node))
                            .unwrap_or_else(|node| (*node).clone());
